mapper.sql:
SELECT ROW_NUMBER() OVER(ORDER BY A.REG_DTTM DESC) AS LINE_NO , COUNT(*) OVER() AS TOTAL_CNT , A.SBJCT_TMPLT_ID , A.SBJCTNM , A.CRCLMN_NO AS SBJCT_CD , A.SBJCT_YR , A.SBJCT_SMSTR , A.SBJCT_GBNCD , A.SBJCT_TYCD , A.LCTR_GBNCD , ORG.ORGNM , SBJCT_TYCD_CD.CDNM AS SBJCT_TYCDNM , LCTR_GBNCD_CD.CDNM AS LCTR_GBNCDNM , A.USEYN , A.DELYN , B.SMSTR_CHRT_ID , B.ORG_ID , B.DGRS_YR , B.DGRS_SMSTR_CHRT FROM TB_LMS_SBJCT_TMPLT A INNER JOIN TB_LMS_SMSTR_CHRT B ON B.SMSTR_CHRT_ID = A.SMSTR_CHRT_ID LEFT JOIN TB_LMS_ORG ORG ON ORG.ORG_ID = B.ORG_ID LEFT JOIN TB_LMS_CMMN_CD SBJCT_TYCD_CD ON SBJCT_TYCD_CD.LANG_CD = NVL(#{langCd}, 'ko') AND SBJCT_TYCD_CD.UP_CD = 'SBJCT_TYCD' AND SBJCT_TYCD_CD.CD = A.SBJCT_TYCD LEFT JOIN TB_LMS_CMMN_CD LCTR_GBNCD_CD ON LCTR_GBNCD_CD.LANG_CD = NVL(#{langCd}, 'ko') AND LCTR_GBNCD_CD.UP_CD = 'LCTR_GBNCD' AND LCTR_GBNCD_CD.CD = A.LCTR_GBNCD WHERE 1 = 1 AND A.DELYN = 'N' AND B.ORG_ID = #{orgId}
AND A.SMSTR_CHRT_ID = #{smstrChrtId}
AND A.SBJCT_YR = #{sbjctYr}
AND TRIM(A.SBJCT_SMSTR) = #{sbjctSmstr}
AND A.SBJCT_TYCD = #{sbjctTycd}
AND A.SBJCTNM LIKE FN_LIKE_VAL(#{searchValue})
ORDER BY A.REG_DTTM DESC

mapper.select:
/* SQL ID : SbjctTmpltDAO.selectSbjctTmpltDupCnt 설 명 : 과목명/과목코드 중복 체크 */ SELECT COUNT(1) FROM TB_LMS_SBJCT_TMPLT A JOIN TB_LMS_SMSTR_CHRT B ON B.SMSTR_CHRT_ID = A.SMSTR_CHRT_ID WHERE A.DELYN = 'N' AND B.ORG_ID = #{orgId} AND B.SMSTR_CHRT_ID = #{smstrChrtId}
AND A.SBJCT_TMPLT_ID != #{sbjctTmpltId}
AND LOWER(TRIM(A.SBJCTNM)) = LOWER(TRIM(#{sbjctnm}))
AND LOWER(TRIM(A.CRCLMN_NO)) = LOWER(TRIM(#{sbjctCd}))
AND 1 = 0

/*
    SQL ID : SbjctTmpltDAO.selectSbjctTmpltSmstrChrtCnt
    설  명 : 과목 학기/기수 유효성 체크
*/
SELECT COUNT(1)
  FROM TB_LMS_SMSTR_CHRT
 WHERE SMSTR_CHRT_ID = #{smstrChrtId}
   AND ORG_ID = #{orgId}

mapper.insert:
/*
    SQL ID : SbjctTmpltDAO.insertSbjctTmplt
    설  명 : 과목 등록
*/
INSERT INTO TB_LMS_SBJCT_TMPLT (
    SBJCT_TMPLT_ID
  , SBJCT_REF_TYCD
  , SMSTR_CHRT_ID
  , SBJCTNM
  , SBJCT_EXPLN
  , SBJCT_YR
  , SBJCT_SMSTR
  , SBJCT_TYCD
  , USEYN
  , DELYN
  , RGTR_ID
  , REG_DTTM
  , MDFR_ID
  , MOD_DTTM
  , LCTR_GBNCD
  , CRCLMN_NO
) VALUES (
    #{sbjctTmpltId}
  , #{sbjctRefTycd}
  , #{smstrChrtId}
  , #{sbjctnm}
  , #{sbjctExpln}
  , #{sbjctYr}
  , #{sbjctSmstr}
  , #{sbjctTycd}
  , #{useyn}
  , #{delyn}
  , #{rgtrId}
  , FN_DTTM()
  , #{mdfrId}
  , FN_DTTM()
  , #{lctrGbncd}
  , #{sbjctCd}
)

/*
    SQL ID : SbjctTmpltDAO.insertSbjctTmpltList
    설  명 : 과목 엑셀 업로드 검증이 완료된 목록을 벌크 등록한다.
*/
INSERT ALL

    INTO TB_LMS_SBJCT_TMPLT (
        SBJCT_TMPLT_ID
      , SBJCT_REF_TYCD
      , SMSTR_CHRT_ID
      , SBJCTNM
      , SBJCT_EXPLN
      , SBJCT_YR
      , SBJCT_SMSTR
      , SBJCT_TYCD
      , USEYN
      , DELYN
      , RGTR_ID
      , REG_DTTM
      , MDFR_ID
      , MOD_DTTM
      , LCTR_GBNCD
      , CRCLMN_NO
    ) VALUES (
        #{item.sbjctTmpltId}
      , #{item.sbjctRefTycd}
      , #{item.smstrChrtId}
      , #{item.sbjctnm}
      , #{item.sbjctExpln}
      , #{item.sbjctYr}
      , #{item.sbjctSmstr}
      , #{item.sbjctTycd}
      , #{item.useyn}
      , #{item.delyn}
      , #{item.rgtrId}
      , FN_DTTM()
      , #{item.mdfrId}
      , FN_DTTM()
      , #{item.lctrGbncd}
      , #{item.sbjctCd}
    )

SELECT 1 FROM DUAL

mapper.update:
/*
    SQL ID : SbjctTmpltDAO.updateSbjctTmplt
    설  명 : 과목 수정
*/
UPDATE TB_LMS_SBJCT_TMPLT
   SET SBJCT_REF_TYCD = #{sbjctRefTycd}
     , SMSTR_CHRT_ID  = #{smstrChrtId}
     , SBJCTNM        = #{sbjctnm}
     , SBJCT_EXPLN    = #{sbjctExpln}
     , SBJCT_YR       = #{sbjctYr}
     , SBJCT_SMSTR    = #{sbjctSmstr}
     , SBJCT_TYCD     = #{sbjctTycd}
     , USEYN          = #{useyn}
     , MDFR_ID        = #{mdfrId}
     , MOD_DTTM       = FN_DTTM()
     , LCTR_GBNCD     = #{lctrGbncd}
     , CRCLMN_NO      = #{sbjctCd}
 WHERE SBJCT_TMPLT_ID = #{sbjctTmpltId}
   AND DELYN = 'N'
